const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = oneWeekAgo.toISOString();
const repo = $vars.github_repo || 'claude-builders-bounty/claude-builders-bounty';
const lang = $vars.language || 'EN';
const channel = $vars.destination_channel || 'general';

return [{
  json: {
    repo,
    since,
    now: now.toISOString(),
    lang,
    channel
  }
}];

const commits = $input.first().json;
const issues = $input.all()[1].json;
const prs = $input.all()[2].json;

// Filter merged PRs by date
const since = $input.all()[0].json.since;
const sinceDate = new Date(since);
const mergedPRs = (Array.isArray(prs) ? prs : []).filter(pr => {
  if (!pr.merged_at) return false;
  return new Date(pr.merged_at) >= sinceDate;
});

// Filter issues closed this week
const closedIssues = (Array.isArray(issues) ? issues : []).filter(issue => {
  if (!issue.closed_at) return false;
  return new Date(issue.closed_at) >= sinceDate;
});

// Filter PRs out of issues list (GitHub returns PRs as issues too)
const realIssues = closedIssues.filter(i => !i.pull_request);

const commitList = (Array.isArray(commits) ? commits : []).map(c => ({
  message: c.commit?.message?.split('\n')[0] || 'No message',
  author: c.commit?.author?.name || 'Unknown',
  date: c.commit?.author?.date || ''
}));

const prList = mergedPRs.map(p => ({
  title: p.title || 'Untitled',
  author: p.user?.login || 'Unknown',
  number: p.number,
  merged_at: p.merged_at
}));

const issueList = realIssues.map(i => ({
  title: i.title || 'Untitled',
  author: i.user?.login || 'Unknown',
  number: i.number,
  closed_at: i.closed_at
}));

return [{
  json: {
    repo: $input.all()[0].json.repo,
    since: since,
    lang: $input.all()[0].json.lang,
    channel: $input.all()[0].json.channel,
    commits: commitList,
    merged_prs: prList,
    closed_issues: issueList,
    commit_count: commitList.length,
    pr_count: prList.length,
    issue_count: issueList.length
  }
}];

const data = $input.first().json;
const lang = data.lang || 'EN';

const enPrompt = `You are a technical writer creating a weekly development summary for the repository ${data.repo}.

Here is the activity for the week of ${new Date(data.since).toDateString()}:

**Commits (${data.commit_count}):**
${data.commits.map(c => `- ${c.message} by ${c.author}`).join('\n') || 'None'}

**Merged Pull Requests (${data.pr_count}):**
${data.merged_prs.map(p => `- #${p.number}: ${p.title} by @${p.author}`).join('\n') || 'None'}

**Closed Issues (${data.issue_count}):**
${data.closed_issues.map(i => `- #${i.number}: ${i.title} by @${i.author}`).join('\n') || 'None'}

Write a concise, engaging narrative summary (3-5 paragraphs) highlighting key achievements, important changes, and contributor highlights. Keep it professional but approachable.`;

const frPrompt = `Vous êtes un rédacteur technique créant un résumé de développement hebdomadaire pour le dépôt ${data.repo}.

Voici l'activité de la semaine du ${new Date(data.since).toDateString()} :

**Commits (${data.commit_count}) :**
${data.commits.map(c => `- ${c.message} par ${c.author}`).join('\n') || 'Aucun'}

**Pull Requests fusionnées (${data.pr_count}) :**
${data.merged_prs.map(p => `- #${p.number} : ${p.title} par @${p.author}`).join('\n') || 'Aucune'}

**Issues fermées (${data.issue_count}) :**
${data.closed_issues.map(i => `- #${i.number} : ${i.title} par @${i.author}`).join('\n') || 'Aucune'}

Rédigez un résumé narratif concis et engageant (3-5 paragraphes) mettant en avant les réalisations clés, les changements importants et les contributeurs. Gardez un ton professionnel mais accessible.`;

const prompt = lang === 'FR' ? frPrompt : enPrompt;

return [{
  json: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 1500,
    messages: [
      { role: 'user', content: prompt }
    ]
  }
}];

const claudeResponse = $input.first().json;
const originalData = $input.all()[0].json;

const summary = claudeResponse.content?.[0]?.text || 'No summary generated.';

return [{
  json: {
    repo: originalData.repo,
    since: originalData.since,
    lang: originalData.lang,
    channel: originalData.channel,
    content: summary,
    raw: claudeResponse
  }
}];
